173	    constructor(option: VisualMappingOption) {
174	        const mappingMethod = option.mappingMethod;
175	        const visualType = option.type;
176	
177	        const thisOption: VisualMappingInnerOption = this.option = zrUtil.clone(option) as VisualMappingInnerOption;
178	
179	        this.type = visualType;
180	        this.mappingMethod = mappingMethod;
181	
182	        this._normalizeData = normalizers[mappingMethod];
183	        const visualHandler = VisualMapping.visualHandlers[visualType];
184	
185	        this.applyVisual = visualHandler.applyVisual;
186	
187	        this.getColorMapper = visualHandler.getColorMapper;
188	
189	        this._normalizedToVisual = visualHandler._normalizedToVisual[mappingMethod];
190	
191	        if (mappingMethod === 'piecewise') {
192	            normalizeVisualRange(thisOption);
193	            preprocessForPiecewise(thisOption);
194	        }
195	        else if (mappingMethod === 'category') {
196	            thisOption.categories
197	                ? preprocessForSpecifiedCategory(thisOption)
198	                // categories is ordinal when thisOption.categories not specified,
199	                // which need no more preprocess except normalize visual.
200	                : normalizeVisualRange(thisOption, true);
201	        }
202	        else { // mappingMethod === 'linear' or 'fixed'
203	            zrUtil.assert(mappingMethod !== 'linear' || thisOption.dataExtent);
204	            normalizeVisualRange(thisOption);
205	        }
206	    }
207	
208	    mapValueToVisual(value: RawValue): VisualValue {
209	        const normalized = this._normalizeData(value);
210	        return this._normalizedToVisual(normalized, value);
211	    }
