217	    static visualHandlers: {[key in BuiltinVisualProperty]: VisualHandler} = {
218	        color: {
219	            applyVisual: makeApplyVisual('color'),
220	            getColorMapper: function () {
221	                const thisOption = this.option;
222	
223	                return zrUtil.bind(
224	                    thisOption.mappingMethod === 'category'
225	                        ? function (
226	                            this: VisualMapping,
227	                            value: NormalizedValue | RawValue,
228	                            isNormalized?: boolean
229	                        ): ColorString {
230	                            !isNormalized && (value = this._normalizeData(value));
231	                            return doMapCategory.call(this, value) as ColorString;
232	                        }
233	                        : function (
234	                            this: VisualMapping,
235	                            value: NormalizedValue | RawValue,
236	                            isNormalized?: boolean,
237	                            out?: number[]
238	                        ): number[] | string {
239	                            // If output rgb array
240	                            // which will be much faster and useful in pixel manipulation
241	                            const returnRGBArray = !!out;
242	                            !isNormalized && (value = this._normalizeData(value));
243	                            out = zrColor.fastLerp(value as NormalizedValue, thisOption.parsedVisual, out);
