365	     * Visual can be Object or Array or primary type.
366	     */
367	    static eachVisual<Ctx, T>(
368	        visual: T | T[] | Dictionary<T>,
369	        callback: (visual: T, key?: string | number) => void,
370	        context?: Ctx
371	    ) {
372	        if (zrUtil.isObject(visual)) {
373	            zrUtil.each(visual as Dictionary<T>, callback, context);
374	        }
375	        else {
376	            callback.call(context, visual);
377	        }
