387	    static mapVisual<Ctx, T>(
388	        visual: T | T[] | Dictionary<T>,
389	        callback: (visual: T, key?: string | number) => T | T[] | Dictionary<T>,
390	        context?: Ctx
391	    ) {
392	        let isPrimary: boolean;
393	        let newVisual: T | T[] | Dictionary<T> = zrUtil.isArray(visual)
394	            ? []
395	            : zrUtil.isObject(visual)
396	            ? {}
397	            : (isPrimary = true, null);
398	
399	        VisualMapping.eachVisual(visual, function (v, key) {
400	            const newVal = callback.call(context, v, key);
401	            isPrimary ? (newVisual = newVal) : ((newVisual as Dictionary<T>)[key as string] = newVal as T);
402	        });
403	        return newVisual;
