423	    /**
424	     * Give order to visual types, considering colorSaturation, colorAlpha depends on color.
425	     *
426	     * @public
427	     * @param {(Object|Array)} visualTypes If Object, like: {color: ..., colorSaturation: ...}
428	     *                                     IF Array, like: ['color', 'symbol', 'colorSaturation']
429	     * @return {Array.<string>} Sorted visual types.
430	     */
431	    static prepareVisualTypes(
432	        visualTypes: {[key in BuiltinVisualProperty]?: any} | BuiltinVisualProperty[]
433	    ) {
434	        if (zrUtil.isArray(visualTypes)) {
435	            visualTypes = visualTypes.slice();
436	        }
437	        else if (isObject(visualTypes)) {
438	            const types: BuiltinVisualProperty[] = [];
439	            each(visualTypes, function (item: unknown, type: BuiltinVisualProperty) {
440	                types.push(type);
441	            });
442	            visualTypes = types;
443	        }
444	        else {
445	            return [];
446	        }
447	
448	        visualTypes.sort(function (type1: BuiltinVisualProperty, type2: BuiltinVisualProperty) {
449	            // color should be front of colorSaturation, colorAlpha, ...
450	            // symbol and symbolSize do not matter.
451	            return (type2 === 'color' && type1 !== 'color' && type1.indexOf('color') === 0)
452	                ? 1 : -1;
453	        });
454	
455	        return visualTypes;
456	    }
457	
458	    /**
459	     * 'color', 'colorSaturation', 'colorAlpha', ... are depends on 'color'.
460	     * Other visuals are only depends on themself.
461	     */
462	    static dependsOn(visualType1: BuiltinVisualProperty, visualType2: BuiltinVisualProperty) {
463	        return visualType2 === 'color'
464	            ? !!(visualType1 && visualType1.indexOf(visualType2) === 0)
465	            : visualType1 === visualType2;
466	    }
467	
468	    /**
469	     * @param value
470	     * @param pieceList [{value: ..., interval: [min, max]}, ...]
471	     *                         Always from small to big.
472	     * @param findClosestWhenOutside Default to be false
473	     * @return index
474	     */
475	    static findPieceIndex(value: number, pieceList: VisualMappingPiece[], findClosestWhenOutside?: boolean): number {
476	        let possibleI: number;
477	        let abs = Infinity;
478	
479	        // value has the higher priority.
480	        for (let i = 0, len = pieceList.length; i < len; i++) {
481	            const pieceValue = pieceList[i].value;
482	            if (pieceValue != null) {
483	                if (pieceValue === value
484	                    // FIXME
485	                    // It is supposed to compare value according to value type of dimension,
486	                    // but currently value type can exactly be string or number.
487	                    // Compromise for numeric-like string (like '12'), especially
488	                    // in the case that visualMap.categories is ['22', '33'].
489	                    || (zrUtil.isString(pieceValue) && pieceValue === value + '')
490	                ) {
491	                    return i;
492	                }
493	                findClosestWhenOutside && updatePossible(pieceValue as number, i);
494	            }
495	        }
496	
497	        for (let i = 0, len = pieceList.length; i < len; i++) {
498	            const piece = pieceList[i];
499	            const interval = piece.interval;
500	            const close = piece.close;
501	
502	            if (interval) {
503	                if (interval[0] === -Infinity) {
504	                    if (littleThan(close[1], value, interval[1])) {
505	                        return i;
506	                    }
507	                }
508	                else if (interval[1] === Infinity) {
509	                    if (littleThan(close[0], interval[0], value)) {
510	                        return i;
511	                    }
512	                }
513	                else if (
514	                    littleThan(close[0], interval[0], value)
515	                    && littleThan(close[1], value, interval[1])
516	                ) {
517	                    return i;
518	                }
519	                findClosestWhenOutside && updatePossible(interval[0], i);
520	                findClosestWhenOutside && updatePossible(interval[1], i);
521	            }
522	        }
523	
524	        if (findClosestWhenOutside) {
525	            return value === Infinity
526	                ? pieceList.length - 1
527	                : value === -Infinity
528	                ? 0
529	                : possibleI;
530	        }
531	
532	        function updatePossible(val: number, index: number) {
533	            const newAbs = Math.abs(val - value);
534	            if (newAbs < abs) {
535	                abs = newAbs;
536	                possibleI = index;
537	            }
538	        }
539	
540	    }
541	}
