543	function preprocessForPiecewise(thisOption: VisualMappingInnerOption) {
544	    const pieceList = thisOption.pieceList;
545	    thisOption.hasSpecialVisual = false;
546	
547	    zrUtil.each(pieceList, function (piece, index) {
548	        piece.originIndex = index;
549	        // piece.visual is "result visual value" but not
550	        // a visual range, so it does not need to be normalized.
551	        if (piece.visual != null) {
552	            thisOption.hasSpecialVisual = true;
553	        }
554	    });
555	}
556	
557	function preprocessForSpecifiedCategory(thisOption: VisualMappingInnerOption) {
558	    // Hash categories.
559	    const categories = thisOption.categories;
560	    const categoryMap: VisualMappingInnerOption['categoryMap'] = thisOption.categoryMap = {};
561	
562	    let visual = thisOption.visual;
563	    each(categories, function (cate, index) {
564	        categoryMap[cate] = index;
565	    });
566	
567	    // Process visual map input.
568	    if (!zrUtil.isArray(visual)) {
569	        const visualArr: VisualValue[] = [];
570	
571	        if (zrUtil.isObject(visual)) {
572	            each(visual, function (v, cate) {
573	                const index = categoryMap[cate];
574	                visualArr[index != null ? index : CATEGORY_DEFAULT_VISUAL_INDEX] = v;
575	            });
576	        }
577	        else { // Is primary type, represents default visual.
578	            visualArr[CATEGORY_DEFAULT_VISUAL_INDEX] = visual;
579	        }
580	
581	        visual = setVisualToOption(thisOption, visualArr);
582	    }
583	
584	    // Remove categories that has no visual,
585	    // then we can mapping them to CATEGORY_DEFAULT_VISUAL_INDEX.
586	    for (let i = categories.length - 1; i >= 0; i--) {
587	        if (visual[i] == null) {
588	            delete categoryMap[categories[i]];
589	            categories.pop();
590	        }
591	    }
592	}
593	
594	function normalizeVisualRange(thisOption: VisualMappingInnerOption, isCategory?: boolean) {
595	    const visual = thisOption.visual;
596	    const visualArr: VisualValue[] = [];
597	
598	    if (zrUtil.isObject(visual)) {
599	        each(visual, function (v) {
600	            visualArr.push(v);
601	        });
602	    }
603	    else if (visual != null) {
604	        visualArr.push(visual);
605	    }
606	
607	    const doNotNeedPair = {color: 1, symbol: 1};
608	
609	    if (!isCategory
610	        && visualArr.length === 1
611	        && !doNotNeedPair.hasOwnProperty(thisOption.type)
612	    ) {
613	        // Do not care visualArr.length === 0, which is illegal.
614	        visualArr[1] = visualArr[0];
615	    }
616	
617	    setVisualToOption(thisOption, visualArr);
618	}
619	
620	function makePartialColorVisualHandler(
621	    applyValue: (prop: VisualValue, value: NormalizedValue) => VisualValue
622	): VisualHandler {
623	    return {
624	        applyVisual: function (value, getter, setter) {
625	            // Only used in HSL
626	            const colorChannel = this.mapValueToVisual(value);
627	            // Must not be array value
628	            setter('color', applyValue(getter('color'), colorChannel as number));
629	        },
630	        _normalizedToVisual: createNormalizedToNumericVisual([0, 1])
631	    };
632	}
633	
634	function doMapToArray(this: VisualMapping, normalized: NormalizedValue): VisualValue {
635	    const visual = this.option.visual as VisualValue[];
636	    return visual[
637	        Math.round(linearMap(normalized, [0, 1], [0, visual.length - 1], true))
638	    ] || {} as any;    // TODO {}?
639	}
640	
641	function makeApplyVisual(visualType: string): VisualHandler['applyVisual'] {
642	    return function (value, getter, setter) {
643	        setter(visualType, this.mapValueToVisual(value));
644	    };
645	}
646	
647	function doMapCategory(this: VisualMapping, normalized: NormalizedValue): VisualValue {
648	    const visual = this.option.visual as Dictionary<any>;
649	    return visual[
650	        (this.option.loop && normalized !== CATEGORY_DEFAULT_VISUAL_INDEX)
651	            ? normalized % visual.length
652	            : normalized
653	    ];
654	}
655	
656	function doMapFixed(this: VisualMapping): VisualValue {
657	    // visual will be convert to array.
658	    return (this.option.visual as VisualValue[])[0];
659	}
660	
661	/**
662	 * Create mapped to numeric visual
663	 */
664	function createNormalizedToNumericVisual(sourceExtent: [number, number]): VisualHandler['_normalizedToVisual'] {
665	    return {
666	        linear: function (normalized) {
667	            return linearMap(normalized, sourceExtent, this.option.visual as [number, number], true);
668	        },
669	        category: doMapCategory,
670	        piecewise: function (normalized, value) {
671	            let result = getSpecifiedVisual.call(this, value);
672	            if (result == null) {
673	                result = linearMap(normalized, sourceExtent, this.option.visual as [number, number], true);
674	            }
675	            return result;
676	        },
677	        fixed: doMapFixed
678	    };
679	}
680	
681	function getSpecifiedVisual(this: VisualMapping, value: number) {
682	    const thisOption = this.option;
683	    const pieceList = thisOption.pieceList;
684	    if (thisOption.hasSpecialVisual) {
685	        const pieceIndex = VisualMapping.findPieceIndex(value, pieceList);
686	        const piece = pieceList[pieceIndex];
687	        if (piece && piece.visual) {
688	            return piece.visual[this.type];
689	        }
690	    }
691	}
692	
693	function setVisualToOption(thisOption: VisualMappingInnerOption, visualArr: VisualValue[]) {
694	    thisOption.visual = visualArr;
695	    if (thisOption.type === 'color') {
696	        thisOption.parsedVisual = zrUtil.map(visualArr, function (item: string) {
697	            const color = zrColor.parse(item);
698	            if (!color && __DEV__) {
699	                warn(`'${item}' is an illegal color, fallback to '#000000'`, true);
700	            }
701	            return color || [0, 0, 0, 1];
702	        });
703	    }
704	    return visualArr;
705	}
706	
707	
708	/**
709	 * Normalizers by mapping methods.
710	 */
711	const normalizers: { [key in MappingMethod]: Normalizer } = {
712	    linear: function (value: RawValue): NormalizedValue {
713	        return linearMap(value as number, this.option.dataExtent, [0, 1], true);
714	    },
715	
716	    piecewise: function (value: RawValue): NormalizedValue {
717	        const pieceList = this.option.pieceList;
718	        const pieceIndex = VisualMapping.findPieceIndex(value as number, pieceList, true);
719	        if (pieceIndex != null) {
720	            return linearMap(pieceIndex, [0, pieceList.length - 1], [0, 1], true);
721	        }
722	    },
723	
724	    category: function (value: RawValue): NormalizedValue {
725	        const index: number = this.option.categories
726	            ? this.option.categoryMap[value]
727	            : value as number; // ordinal value
728	        return index == null ? CATEGORY_DEFAULT_VISUAL_INDEX : index;
729	    },
730	
731	    fixed: zrUtil.noop as Normalizer
732	};
